  useEffect(()=>{let active=true;setRecord(null);setErr('');if(id)void api(`/api/records/${encodeURIComponent(id)}`).then(v=>{if(!active)return;setRecord(v);if(v.events?.length&&!v.response?.body)setSource(current=>current==='response'?'event':current);}).catch(e=>{if(active)setErr(e.message??String(e));});return()=>{active=false;};},[id]);
  const rows=useMemo(()=>{if(!record)return [];const q=filter.trim().toLowerCase();
    if(isHeaderSource(source)){const seen=new Map<string,unknown>();for(const [name,value] of record[source==='requestHeader'?'request':'response']?.headers??[])if(!seen.has(name.toLowerCase()))seen.set(name.toLowerCase(),value);return [...seen].filter(([path,value])=>!q||`${path} ${value}`.toLowerCase().includes(q));}
    const parse=(v:any)=>{if(typeof v!=='string')return v;try{return JSON.parse(v);}catch{return undefined;}};
    const roots=source==='event'?(record.events??[]).slice(0,5).map((e:any)=>parse(e.data)):[parse(record[source]?.body)];
    const seen=new Map<string,unknown>();for(const root of roots)if(root!==null&&typeof root==='object')for(const row of flattenJsonPaths(root))if(!seen.has(row.path))seen.set(row.path,row.value);
    return [...seen].filter(([path,value])=>!q||`${path} ${value}`.toLowerCase().includes(q));},[record,source,filter]);
  const live=target&&targets?.some(t=>t.id===target)?target:'';
