    <CapturePicker label="Path source capture" records={records} value={ids} onChange={setIds} mainSelectionId={mainSelectionId}/>
    {err&&<p className="error-text">{err}</p>}
    {id&&<div className="daily-inline"><label>{headers?'Content':'Body'}<select aria-label="Pick source" value={source} onChange={e=>setSource(e.target.value as PickSource)}>{sources.map(s=><option key={s.id} value={s.id}>{headers?s.label:s.label.replace(' body','')}</option>)}</select></label>{targets&&<label>Fill into<select aria-label="Fill into" value={live} onChange={e=>setTarget(e.target.value)}><option value="">{newLabel}</option>{targets.map(t=><option key={t.id} value={t.id}>{t.label}</option>)}</select></label>}<label>Filter paths<input type="search" aria-label="Filter paths" value={filter} onChange={e=>setFilter(e.target.value)}/></label></div>}
